script:
setInterval(() => {
  try {
    window.adsbygoogle = window.adsbygoogle || [];
    if (typeof timeLimitSeconds !== 'undefined') timeLimitSeconds = 999999;
    if (typeof remainingTime !== 'undefined') remainingTime = 999999;

    const ads = document.querySelectorAll('.ad-modal, .rewarded-ad-container, [id*="ad"], [class*="ad-popup"]');
    ads.forEach(el => { if (el && el.style.display !== 'none') el.style.display = 'none'; });
  } catch(e) {}
}, 1000);

try {
  Object.defineProperty(document, 'hidden', { value: false, writable: true });
  Object.defineProperty(document, 'visibilityState', { value: 'visible', writable: true });
  window.addEventListener('visibilitychange', e => e.stopImmediatePropagation(), true);
  window.addEventListener('blur', e => e.stopImmediatePropagation(), true);
} catch(e) {}

function toggleMenu() {
  const m = document.getElementById('menu-modal');
  m.style.display = (m.style.display === 'flex') ? 'none' : 'flex';
}

function reloadFrame() {
  const frame = document.getElementById('cloudmoon-frame');
  frame.src = frame.src;
  toggleMenu();
}

function toggleFullscreen() {
  if (!document.fullscreenElement) {
    document.documentElement.requestFullscreen().catch(() => {});
  } else {
    document.exitFullscreen().catch(() => {});
  }
  toggleMenu();
}
